function normalizeEntries(raw) {
  const values = Array.isArray(raw) ? raw : (raw ? [raw] : []);
  const out = [];

  for (const entry of values) {
    try {
      const parsed = typeof entry === 'string' ? JSON.parse(entry) : entry;
      if (Array.isArray(parsed)) {
        for (const sub of parsed) {
          if (sub) out.push(sub);
        }
      } else if (parsed) {
        out.push(parsed);
      }
    } catch {
      // ignore malformed entry
    }
  }

  out.sort((a, b) => {
    const da = new Date(a?.date_time || 0).getTime() || 0;
    const db = new Date(b?.date_time || 0).getTime() || 0;
    return da - db;
  });

  const seen = new Set();
  const deduped = [];
  for (const item of out) {
    const key = String(item?.message_id || '') || `${item?.date_time || ''}__${item?.content_text || ''}`;
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(item);
  }

  return deduped;
}

function getNodeJson(name) {
  try {
    return $(name).item.json || {};
  } catch {
    return {};
  }
}

const bufferSource = getNodeJson('Get_Buffer_Data');
const promptSource = getNodeJson('System Promt');
const deduped = normalizeEntries(bufferSource.message);
const textParts = deduped.map((item) => String(item?.content_text || item?.data || '').trim()).filter(Boolean);
const lastItem = deduped.length ? deduped[deduped.length - 1] : null;
const processedMessageIds = deduped.map((item) => String(item?.message_id || '')).filter(Boolean);
const signature = processedMessageIds.length
  ? processedMessageIds.join('|')
  : deduped.map((item) => `${item?.date_time || ''}__${item?.content_text || ''}`).join('|');

return [{
  json: {
    concat_message: textParts.join(' ').replace(/\s+/g, ' ').trim(),
    system_promt: promptSource.aigentss_system_promt || $json.aigentss_system_promt || '',
    buffer_items: deduped,
    buffer_items_count: deduped.length,
    buffer_last_message_id: lastItem?.message_id ? String(lastItem.message_id) : null,
    buffer_last_message_text: lastItem?.content_text || lastItem?.data || null,
    buffer_signature: signature,
    processed_message_ids: processedMessageIds,
  },
}];

const message = items[0].json.body || {};
const content = message.content || '';
const attachments = message.attachments || [];

function makeInternal(url) {
  if (!url) return url;
  const match = String(url).match(/^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud(.*)/);
  if (!match) return url;
  return 'http://' + match[1] + '.ocm.aigentss.cloud:3000' + (match[2] || '');
}

const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url),
}));

let type = 'unknown';
if (attachments.length === 0 && content.trim() !== '') {
  type = 'text';
} else if (attachments.length > 0) {
  if (attachments.every(a => a.file_type === 'image')) {
    type = content.trim() !== '' ? 'image_with_text' : 'image';
  } else if (attachments.every(a => a.file_type === 'audio')) {
    type = 'audio';
  } else if (attachments.every(a => a.file_type === 'location')) {
    type = 'location';
  } else {
    type = 'mixed';
  }
}

return [{
  json: {
    type,
    content_text: content,
    attachments: processedAttachments,
    raw: items[0].json,
  },
}];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const node = items[0].json;
const editFields = $('Edit Fields').item.json;
const rawContent = String(node.content || '');

function lineValue(key) {
  const match = rawContent.match(new RegExp(`^${key}:\\s*(.+?)\\s*$`, 'im'));
  return match ? match[1].trim() : '';
}

const buttonAction = lineValue('button_action');
const buttonPayload = lineValue('button_payload');
const listReplyId = lineValue('list_reply_id');
const buttonText = lineValue('button_text');
const declaredModel = lineValue('model');
const callbackIds = [buttonAction, buttonPayload, listReplyId].filter(Boolean);
const isMoreInfoCallback = callbackIds.some((value) => /(?:^|__)(?:mas_info|more_info)$/i.test(value));
const productMatch = callbackIds.map((value) => value.match(/__product_(.+?)__(?:mas_info|more_info)\b/i)).find(Boolean);
let requestedProductId = productMatch ? productMatch[1].trim() : '';
const titleModelMatch = buttonText.match(/^Info\s+(.+?)\s*$/i);
const callbackModelMatch = callbackIds.map((value) => value.match(/^(.+?)__(?:mas_info|more_info)$/i)).find(Boolean);
const declaredModelIsExact = declaredModel && !/^(?:-|catalog|catalogo|catálogo|vehicle|vehiculo|vehículo)$/i.test(declaredModel);
let requestedModel = declaredModelIsExact
  ? declaredModel
  : (titleModelMatch ? titleModelMatch[1].trim() : '');
if (!requestedModel && callbackModelMatch && !/__product_/i.test(callbackModelMatch[1]) && !/^catalog(?:__|_)/i.test(callbackModelMatch[1])) {
  requestedModel = callbackModelMatch[1].replace(/_+/g, ' ').trim();
}
const callbackState = editFields.body?.conversation?.custom_attributes || {};
if (isMoreInfoCallback && !requestedProductId) {
  requestedProductId = String(callbackState.selected_model_id || callbackState.latest_selected_model_id || '').trim();
}
if (isMoreInfoCallback && !requestedModel) {
  requestedModel = String(callbackState.selected_model || callbackState.latest_selected_model || '').trim();
}

let normalizedContent = rawContent;
if (isMoreInfoCallback && (requestedModel || requestedProductId)) {
  normalizedContent = [
    'callback_intent: vehicle_detail_exact',
    'callback_action: more_info',
    requestedModel ? `selected_model: ${requestedModel}` : '',
    requestedProductId ? `selected_product_id: ${requestedProductId}` : '',
    `callback_id: ${buttonPayload || listReplyId || buttonAction}`,
    `request: Quiero información detallada del vehículo seleccionado${requestedModel ? ` ${requestedModel}` : ''}${requestedProductId ? ` (product_id: ${requestedProductId})` : ''}.`,
  ].filter(Boolean).join('\n');
}

const callbackValue = buttonPayload || listReplyId || buttonAction;
const callbackPlaceholder = /^(?:-|catalog|catalogo|catálogo|vehicle|vehiculo|vehículo|vehicle_schedule|vehicle_visit|techsheet|booking_context_retry)$/i;
const declaredCallbackModel = declaredModel && !callbackPlaceholder.test(declaredModel)
  ? declaredModel
  : '';
function positiveId(value) {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? String(parsed) : '';
}
function uniqueValue(values, normalizer = (value) => String(value || '').trim()) {
  const unique = [...new Set(values.map(normalizer).filter(Boolean))];
  return unique.length === 1 ? unique[0] : '';
}
const replyContext = editFields.body?.content_attributes?.in_reply_to
  || editFields.body?.conversation?.messages?.[0]?.content_attributes?.in_reply_to
  || null;
const replyContextText = typeof replyContext === 'string' ? replyContext : JSON.stringify(replyContext || {});
const quotedProductId = positiveId(replyContextText.match(/(?:__product_|selected_product_id\s*[:=]\s*)(\d+)/i)?.[1]);
const quotedModel = String(replyContextText.match(/(?:selected_model|model)\s*[:=]\s*([^\n",}]+)/i)?.[1] || '').trim();
const exactQuotedModel = quotedModel && !callbackPlaceholder.test(quotedModel) ? quotedModel : '';
const stateProductId = uniqueValue([
  callbackState.selected_model_id,
  callbackState.latest_selected_model_id,
], positiveId);
const stateModel = uniqueValue([
  callbackState.selected_model,
  callbackState.latest_selected_model,
], (value) => {
  const text = String(value || '').trim();
  return text && !callbackPlaceholder.test(text) ? text : '';
});
const vehicleCallback = callbackValue.match(/^vehicle_(visit|schedule)(?:__product_(\d+))?(?:__establishment_(\d+))?$/i);
const catalogScheduleMatch = callbackValue.match(/__product_(\d+)__(?:test_drive|schedule)$/i);
const legacyVisitModelMatch = callbackValue.match(/^(.+?)__(?:verlo_en_persona|ver_en_persona)$/i);
const legacyScheduleModelMatch = callbackValue.match(/^(.+?)__(?:agendar_test_drive|book_test_drive|test_drive)$/i);
const legacyVehicleAction = /^(?:see_in_person|verlo_en_persona|ver_en_persona)$/i.test(callbackValue) || legacyVisitModelMatch
  ? 'visit'
  : (/^(?:agendar_test_drive|book_test_drive|test_drive)$/i.test(callbackValue) || catalogScheduleMatch || legacyScheduleModelMatch ? 'schedule' : '');
if (vehicleCallback || legacyVehicleAction) {
  const action = String(vehicleCallback?.[1] || legacyVehicleAction).toLowerCase();
  const encodedModel = legacyVisitModelMatch?.[1] || legacyScheduleModelMatch?.[1] || '';
  const callbackModel = declaredCallbackModel
    || (encodedModel ? encodedModel.replace(/_+/g, ' ').trim() : '')
    || exactQuotedModel
    || stateModel;
  const callbackProductId = positiveId(vehicleCallback?.[2])
    || positiveId(catalogScheduleMatch?.[1])
    || quotedProductId
    || stateProductId;
  const callbackEstablishmentId = vehicleCallback?.[3] || String(callbackState.selected_establishment_id || callbackState.establishment_id || '').trim();
  normalizedContent = [
    `booking_action: ${action === 'visit' ? 'visit_vehicle' : 'schedule_vehicle'}`,
    callbackModel ? `selected_model: ${callbackModel}` : '',
    callbackProductId ? `selected_product_id: ${callbackProductId}` : '',
    callbackEstablishmentId ? `selected_establishment_id: ${callbackEstablishmentId}` : '',
    `booking_callback: ${callbackValue}`,
  ].filter(Boolean).join('\n');
}

if (/^(?:catalog|other_models|ver_otros_modelos)$/i.test(callbackValue)) {
  normalizedContent = [
    'catalog_action: show_all',
    `catalog_callback: ${callbackValue}`,
    'request: Muéstrame el catálogo completo',
  ].join('\n');
}

// The technical-sheet callback is normalized into an explicit intent so the
// workflow can deliver the file deterministically instead of letting the raw
// button text fall through to the agent and loop.
const techsheetCallback = callbackValue.match(/^techsheet(?:__product_(\d+))?$/i);
if (techsheetCallback) {
  const techsheetProductId = positiveId(techsheetCallback[1]) || quotedProductId || stateProductId;
  normalizedContent = [
    'callback_intent: techsheet_requested',
    techsheetProductId ? `selected_product_id: ${techsheetProductId}` : '',
    `callback_id: ${callbackValue}`,
    'request: El cliente pidió la ficha técnica del vehículo. El workflow entrega el archivo de forma determinista: responde en una sola frase presentandola, sin repetir los detalles del vehículo y sin inventar enlaces.',
  ].filter(Boolean).join('\n');
}

const bookingMatch = callbackValue.match(/^(booking_(?:(?:confirm|select)_establishment_\d+(?:_city_[a-f0-9]+)?(?:_product_\d+)?|other_city(?:_product_\d+)?|city_[a-f0-9]+(?:_product_\d+)?|cities_(?:page_\d+|retry)(?:_product_\d+)?)|cities|retry)$/i);
const bookingCallback = bookingMatch ? bookingMatch[1].toLowerCase() : '';
const bookingProductId = bookingCallback.match(/_product_(\d+)$/)?.[1] || '';
const baseBookingCallback = bookingCallback.replace(/_product_\d+$/, '');
const establishmentMatch = bookingCallback.match(/^booking_(?:confirm|select)_establishment_(\d+)(?:_city_([a-f0-9]+))?(?:_product_(\d+))?$/);
const cityMatch = baseBookingCallback.match(/^booking_city_([a-f0-9]+)$/);
const pageMatch = baseBookingCallback.match(/^booking_cities_page_(\d+)$/);
if (establishmentMatch) {
  let establishmentCity = '';
  try {
    establishmentCity = establishmentMatch[2] ? Buffer.from(establishmentMatch[2], 'hex').toString('utf8').trim() : '';
  } catch {}
  normalizedContent = [
    'booking_action: confirm_establishment',
    `selected_establishment_id: ${establishmentMatch[1]}`,
    establishmentMatch[3] || bookingProductId ? `selected_product_id: ${establishmentMatch[3] || bookingProductId}` : '',
    establishmentCity ? `selected_city: ${establishmentCity}` : '',
    `booking_callback: ${bookingCallback}`,
  ].filter(Boolean).join('\n');
} else if (cityMatch) {
  let selectedCity = '';
  try {
    selectedCity = Buffer.from(cityMatch[1], 'hex').toString('utf8').trim();
  } catch {}
  normalizedContent = [
    'booking_action: select_city',
    `selected_city: ${selectedCity}`,
    bookingProductId ? `selected_product_id: ${bookingProductId}` : '',
    `booking_callback: ${bookingCallback}`,
  ].filter(Boolean).join('\n');
} else if (baseBookingCallback === 'booking_other_city') {
  normalizedContent = [
    'booking_action: choose_other_city',
    'booking_city_page: 0',
    bookingProductId ? `selected_product_id: ${bookingProductId}` : '',
    `booking_callback: ${bookingCallback}`,
  ].filter(Boolean).join('\n');
} else if (pageMatch || bookingCallback === 'cities') {
  normalizedContent = [
    'booking_action: list_cities',
    `booking_city_page: ${pageMatch ? pageMatch[1] : 0}`,
    bookingProductId ? `selected_product_id: ${bookingProductId}` : '',
    `booking_callback: ${bookingCallback}`,
  ].filter(Boolean).join('\n');
} else if (baseBookingCallback === 'booking_cities_retry' || bookingCallback === 'retry') {
  normalizedContent = [
    'booking_action: list_cities',
    'booking_city_page: 0',
    'booking_retry_attempt: 1',
    bookingProductId ? `selected_product_id: ${bookingProductId}` : '',
    `booking_callback: ${bookingCallback}`,
  ].filter(Boolean).join('\n');
}

const slotMatch = callbackValue.match(/^booking_slot__p_(\d+)__e_(\d+)__d_(\d{8})__t_(\d{4})$/i);
const slotsPageMatch = callbackValue.match(/^booking_slots__p_(\d+)__e_(\d+)__d_(\d{8})__page_(\d+)$/i);
const bookingDateMatch = callbackValue.match(/^booking_choose_date__p_(\d+)__e_(\d+)$/i);
const bookingRetryMatch = callbackValue.match(/^booking_(availability|create|context)_retry__p_(\d+)(?:__e_(\d+))?(?:__c_([a-f0-9]+))?(?:__d_(\d{8}))?(?:__t_(\d{4}))?$/i);
const timeframeMatch = callbackValue.match(/^booking_timeframe__days_(\d+)__p_(\d+)__e_(\d+)__d_(\d{8})__t_(\d{4})$/i);
function compactDate(value) {
  return value ? `${value.slice(0, 4)}-${value.slice(4, 6)}-${value.slice(6, 8)}` : '';
}
function compactTime(value) {
  return value ? `${value.slice(0, 2)}:${value.slice(2, 4)}` : '';
}
if (slotMatch) {
  normalizedContent = [
    'booking_action: select_slot',
    `selected_product_id: ${slotMatch[1]}`,
    `selected_establishment_id: ${slotMatch[2]}`,
    `selected_date: ${compactDate(slotMatch[3])}`,
    `selected_time: ${compactTime(slotMatch[4])}`,
    `booking_callback: ${callbackValue}`,
  ].join('\n');
} else if (slotsPageMatch) {
  normalizedContent = [
    'booking_action: list_slots',
    `selected_product_id: ${slotsPageMatch[1]}`,
    `selected_establishment_id: ${slotsPageMatch[2]}`,
    `selected_date: ${compactDate(slotsPageMatch[3])}`,
    `booking_slots_page: ${slotsPageMatch[4]}`,
    `booking_callback: ${callbackValue}`,
  ].join('\n');
} else if (bookingDateMatch) {
  normalizedContent = [
    'booking_action: select_date',
    `selected_product_id: ${bookingDateMatch[1]}`,
    `selected_establishment_id: ${bookingDateMatch[2]}`,
    `booking_callback: ${callbackValue}`,
  ].join('\n');
} else if (bookingRetryMatch) {
  let retryCity = '';
  try { retryCity = bookingRetryMatch[4] ? Buffer.from(bookingRetryMatch[4], 'hex').toString('utf8').trim() : ''; } catch {}
  normalizedContent = [
    `booking_action: retry_${bookingRetryMatch[1].toLowerCase()}`,
    `selected_product_id: ${bookingRetryMatch[2]}`,
    positiveId(bookingRetryMatch[3]) ? `selected_establishment_id: ${positiveId(bookingRetryMatch[3])}` : '',
    retryCity ? `selected_city: ${retryCity}` : '',
    bookingRetryMatch[5] ? `selected_date: ${compactDate(bookingRetryMatch[5])}` : '',
    bookingRetryMatch[6] ? `selected_time: ${compactTime(bookingRetryMatch[6])}` : '',
    `booking_callback: ${callbackValue}`,
  ].filter(Boolean).join('\n');
} else if (timeframeMatch) {
  normalizedContent = [
    'booking_action: select_purchase_timeframe',
    `purchase_timeframe_days: ${timeframeMatch[1]}`,
    `selected_product_id: ${timeframeMatch[2]}`,
    `selected_establishment_id: ${timeframeMatch[3]}`,
    `selected_date: ${compactDate(timeframeMatch[4])}`,
    `selected_time: ${compactTime(timeframeMatch[5])}`,
    `booking_callback: ${callbackValue}`,
  ].join('\n');
}

const submittedFlowToken = lineValue('flow_token');
const flowContextMatch = submittedFlowToken.match(/^fecha_agendamiento-v2-([A-Za-z0-9_-]+)$/);
if (flowContextMatch) {
  try {
    const tokenContext = JSON.parse(Buffer.from(flowContextMatch[1], 'base64url').toString('utf8'));
    const tokenProductId = positiveId(tokenContext.p);
    const tokenEstablishmentId = positiveId(tokenContext.e);
    const tokenServiceId = positiveId(tokenContext.s);
    const tokenSelectedCity = String(tokenContext.sc || '').trim();
    const tokenOriginalCity = String(tokenContext.oc || '').trim();
    if (tokenContext.v === 2 && tokenProductId && tokenEstablishmentId && tokenServiceId === '2') {
      normalizedContent = [
        'booking_action: flow_submit',
        `selected_product_id: ${tokenProductId}`,
        `selected_establishment_id: ${tokenEstablishmentId}`,
        `service_id: ${tokenServiceId}`,
        tokenSelectedCity ? `selected_city: ${tokenSelectedCity}` : '',
        tokenOriginalCity ? `original_city: ${tokenOriginalCity}` : '',
        normalizedContent,
      ].filter(Boolean).join('\n');
    }
  } catch {}
}

return [{
  json: {
    type: node.type,
    content_text: normalizedContent,
    raw: editFields,
  },
}];

function nodeJson(name) {
  try {
    return $(name).item.json || {};
  } catch {
    return {};
  }
}

const source = $json.output?.messages || nodeJson('Semantic Response AI Aigent').output?.messages || [];

if (Array.isArray(source) && source.length > 0) {
  return source.map((m, i) => ({
    indx: i,
    sms: m.sms || '',
    url: m.url || '',
    hasUrl: Boolean(m.url && m.url.trim() !== '')
  }));
}

const prep = nodeJson('Prepare Channel Delivery');
const principalReply = nodeJson('Principal AI Agentss 2.2 - WhatsApp Interactive').output?.reply || nodeJson('Principal AI Aigent  2.2').output?.reply || {};
const replyText = String(prep.delivery_text || principalReply.text || '').trim();
const attachments = (Array.isArray(prep.delivery_attachments) && prep.delivery_attachments.length)
  ? prep.delivery_attachments
  : (Array.isArray(principalReply.channel_hints?.attachments) ? principalReply.channel_hints.attachments : []);

if (attachments.length > 0) {
  return attachments.map((attachment, i) => ({
    json: {
      indx: i,
      sms: i === 0 ? replyText : '',
      url: String(attachment?.url || '').trim(),
      hasUrl: Boolean(String(attachment?.url || '').trim())
    }
  }));
}

if (replyText) {
  return [{
    json: {
      indx: 0,
      sms: replyText,
      url: '',
      hasUrl: false
    }
  }];
}

return [];

const event = String($json.body?.event || '').toLowerCase();
const messageType = String($json.body?.message_type || '').toLowerCase();
const isPrivate = Boolean($json.body?.private);

const currentMessage = $json.body?.conversation?.messages?.find(
  msg => String(msg?.id) === String($json.body?.id)
) || {};

const sender = $json.body?.sender || currentMessage.sender || {};
const senderType = String(currentMessage.sender_type || '').toLowerCase();
const senderName = String(sender.name || currentMessage.sender?.name || '').toLowerCase();
const senderEmail = String(sender.email || currentMessage.sender?.email || '').toLowerCase();
const content = String(
  $json.body?.content ??
  currentMessage.content ??
  currentMessage.processed_message_content ??
  ''
).trim();

const isAutomationSender =
  senderName.includes('aigents') ||
  senderEmail.includes('aigentss.com');

const isIncomingUserMessage =
  event === 'message_created' &&
  messageType === 'incoming' &&
  !isPrivate &&
  senderType === 'contact';

const isPublicHumanTakeoverMessage =
  event === 'message_created' &&
  messageType === 'outgoing' &&
  !isPrivate &&
  senderType === 'user' &&
  content.length > 0 &&
  !isAutomationSender;

const shouldContinue = isIncomingUserMessage || isPublicHumanTakeoverMessage;

return [{
  json: {
    ...$json,
    is_user_message: shouldContinue,
    _debug: {
      event,
      message_type: messageType,
      sender_type: senderType,
      private: isPrivate,
      matched_message_id: currentMessage.id || null,
      content_present: content.length > 0,
      automation_sender: isAutomationSender,
      incoming_user_message: isIncomingUserMessage,
      public_human_takeover_message: isPublicHumanTakeoverMessage,
    },
  },
}];

const source = Array.isArray($json.messages) ? $json.messages : (Array.isArray($json.payload) ? $json.payload : []);
const publicMessages = source.filter(message => !Boolean(message?.private));
publicMessages.sort((a, b) => {
  const timeDiff = (Number(a?.created_at) || 0) - (Number(b?.created_at) || 0);
  if (timeDiff !== 0) return timeDiff;
  return (Number(a?.id) || 0) - (Number(b?.id) || 0);
});
function roleFor(message) {
  const senderType = String(message?.sender_type || message?.sender?.type || '').toLowerCase();
  if (senderType === 'contact') return 'cliente';
  if (senderType === 'user') return 'agente';
  if (senderType === 'agentbot' || senderType === 'captain::assistant') return 'bot';
  const messageType = Number(message?.message_type);
  if (messageType === 0) return 'cliente';
  if (messageType === 1) return 'agente';
  return 'sistema';
}
function textFor(message) {
  const content = String(message?.content || message?.processed_message_content || '').trim();
  if (content) return content;
  const attachments = Array.isArray(message?.attachments) ? message.attachments : (message?.attachment ? [message.attachment] : []);
  if (attachments.length > 0) {
    const types = [...new Set(attachments.map(item => String(item?.file_type || 'archivo').trim()).filter(Boolean))];
    return `[adjunto:${types.join(',') || 'archivo'}]`;
  }
  const contentType = String(message?.content_type || '').trim();
  if (contentType && contentType !== 'text') return `[${contentType}]`;
  return '[sin contenido]';
}
const normalized = publicMessages.map(message => `${roleFor(message)}: ${textFor(message)}`);
const limited = normalized.slice(-120);
return [{ json: { conversation_history_text: limited.join('\n'), conversation_message_count: publicMessages.length, conversation_history_truncated: publicMessages.length > limited.length } }];

parameters.text:
=Conversation History:
{{ $json.conversation_history_text }}

Latest User Message:
{{ $json.concat_message }}

