{{ JSON.stringify({first_interaction: $json.first_interaction, entry_source: $json.entry_source, entry_source_confidence: $json.entry_source_confidence, entry_model_hint: $json.entry_model_hint, journey_type: $json.journey_type, journey_step: $json.journey_step, temperature_label: $json.temperature_label, selected_city: $json.selected_city, selected_model: $json.selected_model, selected_establishment_name: $json.selected_establishment_name, booking_personal_data_complete: $json.booking_personal_data_complete}, null, 2) }}

