function currentNormalizedMessage() {
  try { return String($('Normalize All').item.json.content_text || '').trim(); } catch { return ''; }
}
const latestMessage = String(currentNormalizedMessage() || $('Set Contact Context').item.json.concat_message || '').trim();
const normalized = latestMessage.toLowerCase();
const isCatalogShowAll = /\bcatalog_action:\s*show_all\b/i.test(latestMessage);
const canonicalDetail = /\bcallback_intent:\s*vehicle_detail_exact\b/i.test(latestMessage);
const canonicalModelMatch = latestMessage.match(/\bselected_model:\s*(.+?)(?=\s+(?:selected_product_id|callback_id|request|callback_action|callback_intent):|$)/i);
const canonicalProductMatch = latestMessage.match(/\bselected_product_id:\s*([a-z0-9_-]+)/i);
const legacyDetailMatch = latestMessage.match(/^Quiero información detallada del modelo\s+(.+?)(?:\s+\(product_id:\s*(\d+)\))?\.$/i);
const exactDetailModel = canonicalModelMatch?.[1]?.trim() || legacyDetailMatch?.[1]?.trim() || null;
const exactDetailProductRaw = canonicalProductMatch?.[1] || legacyDetailMatch?.[2] || '';
const exactDetailProductId = /^\d+$/.test(exactDetailProductRaw) ? Number(exactDetailProductRaw) : null;
const hasExactDetailCallback = !isCatalogShowAll && Boolean((canonicalDetail || legacyDetailMatch) && (exactDetailModel || exactDetailProductRaw));
const contentAttributes = $('Webhook').item.json.body?.content_attributes || {};
const publicMessageCount = Number($('Format Conversation History').item.json.conversation_message_count || 0);
const state = $('Set Contact Context').item.json.mcp_booking_state || {};
const contact = $('Set Contact Context').item.json.contact_context || {};
const firstInteraction = publicMessageCount <= 1;
const explicitEntrySource = contentAttributes?.meta?.entry_source || contentAttributes?.entry_source || null;

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function catalogRows() {
  try {
    const rows = $('Load Product Catalog').first().json.products;
    const list = typeof rows === 'string' ? JSON.parse(rows) : rows;
    return Array.isArray(list)
      ? list.filter((row) => row && row.name != null && String(row.name).trim())
      : [];
  } catch {
    return [];
  }
}

const STOPWORDS = new Set(['info','informacion','mas','sobre','el','la','los','las','un','una','de','del','quiero','quisiera','necesito','me','interesa','hola','buenas','buenos','dias','tardes','noches','por','favor','para','que','con','kia','auto','carro','vehiculo','modelo','precio','catalogo','ver','tienen','hay','y','o','en','al','su','sus']);

function levenshtein(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i += 1) {
    const row = [i];
    for (let j = 1; j <= b.length; j += 1) {
      row[j] = Math.min(prev[j] + 1, row[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = row;
  }
  return prev[b.length];
}

// Tolerance scales with name length; short names admit a single edit so unrelated
// short tokens cannot claim a match.
function maxDistanceFor(name) {
  if (name.length <= 4) return 1;
  if (name.length <= 7) return 2;
  return 3;
}

function resolveCatalogModel(message) {
  const catalog = catalogRows();
  const normalizedMessage = normalizeText(message);
  if (!catalog.length) return { match: null, ambiguous: false, candidates: [], mode: 'catalog_unavailable' };
  if (!normalizedMessage) return { match: null, ambiguous: false, candidates: [], mode: 'empty_message' };

  const exact = catalog.filter((product) => {
    const name = normalizeText(product.name);
    return name && new RegExp(`(^| )${name}( |$)`).test(normalizedMessage);
  });
  if (exact.length === 1) return { match: exact[0], ambiguous: false, candidates: exact, mode: 'exact' };
  if (exact.length > 1) return { match: null, ambiguous: true, candidates: exact, mode: 'exact_multiple' };

  const tokens = normalizedMessage.split(' ').filter((token) => token.length >= 3 && !STOPWORDS.has(token));
  const scored = [];
  for (const product of catalog) {
    const name = normalizeText(product.name);
    if (!name) continue;
    let best = Infinity;
    for (const token of tokens) {
      const distance = levenshtein(token, name);
      if (distance < best) best = distance;
    }
    if (best <= maxDistanceFor(name)) scored.push({ product, distance: best });
  }
  if (!scored.length) return { match: null, ambiguous: false, candidates: [], mode: 'no_match' };

  scored.sort((a, b) => a.distance - b.distance);
  const bestDistance = scored[0].distance;
  const tied = scored.filter((entry) => entry.distance === bestDistance);
  if (tied.length > 1) return { match: null, ambiguous: true, candidates: tied.map((entry) => entry.product), mode: 'fuzzy_tie' };
  return { match: scored[0].product, ambiguous: false, candidates: [scored[0].product], mode: 'fuzzy' };
}

const resolution = isCatalogShowAll
  ? { match: null, ambiguous: false, candidates: [], mode: 'catalog_request' }
  : resolveCatalogModel(latestMessage);
const resolvedModelName = resolution.match ? String(resolution.match.name).trim() : null;
const resolvedModelId = resolution.match ? Number(resolution.match.id) || null : null;
const messageWordCount = normalizeText(latestMessage).split(' ').filter(Boolean).length;

let entrySource = state.entry_source || null;
let entrySourceConfidence = state.entry_source_confidence || null;
if (!entrySource && firstInteraction) {
  if (explicitEntrySource) {
    entrySource = String(explicitEntrySource);
    entrySourceConfidence = 'high';
  } else if (resolvedModelName && messageWordCount <= 12) {
    entrySource = 'cta_meta_inferred';
    entrySourceConfidence = 'medium';
  } else {
    entrySource = 'direct_message';
    entrySourceConfidence = 'low';
  }
}
const entryModelHint = isCatalogShowAll
  ? null
  : (hasExactDetailCallback ? exactDetailModel : (state.entry_model_hint || resolvedModelName));
const selectedModel = isCatalogShowAll
  ? null
  : (hasExactDetailCallback ? exactDetailModel : (state.selected_model || state.latest_selected_model || resolvedModelName || entryModelHint || null));
const selectedModelId = isCatalogShowAll
  ? null
  : (hasExactDetailCallback ? exactDetailProductId : (state.selected_model_id || state.latest_selected_model_id || resolvedModelId || null));
const needsModelClarification = Boolean(resolution.ambiguous) && !selectedModel;
const selectedEstablishmentId = state.selected_establishment_id || null;
const selectedEstablishmentName = state.selected_establishment_name || null;
function normalizeBookingCity(value) {
  const city = String(value || '').normalize('NFKC').trim().replace(/\s+/g, ' ');
  if (!city || city.length > 60 || /^(?:-|null|undefined|n\/a)$/i.test(city)) return null;
  if (!/^[\p{L}\p{M} .'-]+$/u.test(city)) return null;
  return city.split(' ').map((part) => part
    ? part[0].toLocaleUpperCase('es-VE') + part.slice(1).toLocaleLowerCase('es-VE')
    : part).join(' ');
}
function latestProfileCity(history) {
  const matches = [...String(history || '').matchAll(/\b(?:city|ciudad)\s*:\s*([^\r\n]+)/gi)];
  for (let index = matches.length - 1; index >= 0; index -= 1) {
    const raw = matches[index][1].split(/\s+(?:intent|comments|flow_token|name|identifier|email|selected_model|selected_date|selected_time)\s*:/i)[0];
    const normalizedCity = normalizeBookingCity(raw);
    if (normalizedCity) return normalizedCity;
  }
  return null;
}
const selectedCity = [
  state.selected_city,
  state.raw_custom_attributes?.selected_city,
  state.raw_custom_attributes?.city,
  contact.custom_attributes?.city,
].map(normalizeBookingCity).find(Boolean)
  || latestProfileCity($('Format Conversation History').item.json.conversation_history_text)
  || null;
const purchaseTimeframeDays = Number(state.purchase_timeframe_days ?? NaN);
let temperatureLabel = state.temperature_label || null;
if (!temperatureLabel && Number.isFinite(purchaseTimeframeDays)) {
  if (purchaseTimeframeDays <= 7) temperatureLabel = 'hot_a';
  else if (purchaseTimeframeDays <= 15) temperatureLabel = 'hot_b';
  else if (purchaseTimeframeDays <= 30) temperatureLabel = 'hot_c';
  else if (purchaseTimeframeDays <= 90) temperatureLabel = 'warm';
  else if (purchaseTimeframeDays <= 180) temperatureLabel = 'cold';
  else temperatureLabel = 'very_cold';
}
const temperatureBucket = temperatureLabel ? (['hot_a','hot_b','hot_c','warm'].includes(temperatureLabel) ? 'hot_or_warm' : (temperatureLabel === 'very_cold' ? 'very_cold' : 'cold')) : null;
const bookingPersonalDataComplete = Boolean((state.customer_name || contact.name) && (state.customer_email || contact.email) && (state.customer_identifier || contact.identifier) && (state.customer_phone || contact.phone_number) && selectedCity);
// A model named in the current message is a product question, not a booking one:
// it must be answered with that vehicle's information before any commercial step.
const plainTextTurn = !hasExactDetailCallback
  && !isCatalogShowAll
  && !/\b(?:booking_action|callback_intent|callback_action|button_payload|list_reply_id|flow_token|catalog_action)\s*:/i.test(latestMessage);
const resolvedInCurrentMessage = plainTextTurn
  && ['exact', 'fuzzy'].includes(resolution.mode)
  && Boolean(resolvedModelName);
// A short free-text answer that matches nothing in the catalog means the customer
// tried to name a model and missed. Longer messages are ordinary questions, not
// failed lookups, so they keep the normal conversational path.
const modelLookupFailed = plainTextTurn
  && bookingPersonalDataComplete
  && !selectedModel
  && ['no_match', 'fuzzy_tie', 'exact_multiple'].includes(resolution.mode)
  && messageWordCount > 0
  && messageWordCount <= 6;

// Journey type follows whether a model is known, not the entry source: origin and
// next action are separate dimensions.
const journeyType = (entryModelHint || selectedModel) ? 'cta_model_first' : 'organic_catalog_first';
let journeyStep = hasExactDetailCallback ? 'show_vehicle_detail' : 'conversation_support';
if (!hasExactDetailCallback) {
  if (!bookingPersonalDataComplete) journeyStep = 'collect_profile';
  else if (modelLookupFailed) journeyStep = 'clarify_model';
  else if (needsModelClarification) journeyStep = 'clarify_model';
  else if (resolvedInCurrentMessage) journeyStep = 'show_vehicle_detail';
  else if (!selectedModel) journeyStep = journeyType === 'organic_catalog_first' ? 'show_catalog' : 'confirm_cta_model';
  else if (!Number.isFinite(purchaseTimeframeDays)) journeyStep = 'collect_purchase_timeframe';
  else if (!selectedEstablishmentId) journeyStep = 'resolve_establishment';
  else if (!state.active_appointment_id) journeyStep = 'offer_appointment';
}
return [{ json: {
  first_interaction: firstInteraction,
  entry_source_check_needed: firstInteraction && !state.entry_source,
  entry_source: entrySource,
  entry_source_confidence: entrySourceConfidence,
  entry_model_hint: entryModelHint,
  entry_model_id_hint: selectedModelId,
  journey_type: journeyType,
  journey_step: journeyStep,
  selected_model_id: selectedModelId,
  selected_model: selectedModel,
  selected_establishment_id: selectedEstablishmentId,
  selected_establishment_name: selectedEstablishmentName,
  selected_city: selectedCity,
  booking_personal_data_complete: bookingPersonalDataComplete,
  temperature_label: temperatureLabel,
  temperature_bucket: temperatureBucket,
  model_resolution: {
    mode: resolution.mode,
    matched_model: resolvedModelName,
    matched_model_id: resolvedModelId,
    ambiguous: Boolean(resolution.ambiguous),
    candidates: (resolution.candidates || []).map((item) => ({ id: item.id, name: item.name })),
    source: 'products_table',
  },
  needs_model_clarification: needsModelClarification,
  model_lookup_failed: modelLookupFailed,
  resolved_model_in_current_message: resolvedInCurrentMessage,
  should_send_catalog: isCatalogShowAll || (!hasExactDetailCallback && !modelLookupFailed && journeyType === 'organic_catalog_first' && !selectedModel && !needsModelClarification),
  should_send_vehicle_info: hasExactDetailCallback || resolvedInCurrentMessage || Boolean(selectedModel),
  should_collect_profile: !hasExactDetailCallback && !bookingPersonalDataComplete,
  should_collect_purchase_timeframe: !hasExactDetailCallback && !resolvedInCurrentMessage && !Number.isFinite(purchaseTimeframeDays),
  should_offer_appointment: !hasExactDetailCallback && Boolean(selectedModel && selectedEstablishmentId && Number.isFinite(purchaseTimeframeDays)),
  appointment_offer_status: state.appointment_offer_status || null
} }];

function normalizeEntries(raw) {
  const values = Array.isArray(raw) ? raw : (raw ? [raw] : []);
  const out = [];

  for (const entry of values) {
    try {
      const parsed = typeof entry === 'string' ? JSON.parse(entry) : entry;
      if (Array.isArray(parsed)) {
        for (const sub of parsed) {
          if (sub) out.push(sub);
        }
      } else if (parsed) {
        out.push(parsed);
      }
    } catch {}
  }

  out.sort((a, b) => {
    const da = new Date(a?.date_time || 0).getTime() || 0;
    const db = new Date(b?.date_time || 0).getTime() || 0;
    return da - db;
  });

  const deduped = [];
  const seen = new Set();
  for (const item of out) {
    const key = String(item?.message_id || '') || `${item?.date_time || ''}__${item?.content_text || ''}`;
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(item);
  }

  return deduped;
}

const deduped = normalizeEntries($json.message);
const ids = deduped.map((item) => String(item?.message_id || '')).filter(Boolean);
const signature = ids.length
  ? ids.join('|')
  : deduped.map((item) => `${item?.date_time || ''}__${item?.content_text || ''}`).join('|');

return [{
  json: {
    current_buffer_items: deduped,
    current_buffer_signature: signature,
    current_buffer_last_text: deduped.length ? (deduped[deduped.length - 1].data || deduped[deduped.length - 1].content_text || null) : null,
    current_buffer_last_message_id: deduped.length ? String(deduped[deduped.length - 1].message_id || '') : '',
  },
}];

function getNodeReply(name) {
  try {
    return $(name).item.json.output?.reply || null;
  } catch {
    return null;
  }
}

const reply = $json.output?.reply
  || getNodeReply('Principal AI Agentss 2.2 - WhatsApp Interactive')
  || getNodeReply('Principal AI Aigent  2.2')
  || {};
const hints = reply.channel_hints || {};
const supportsMeta = Boolean($json.supports_meta_interactive);
const channelFamily = String($json.channel_family || 'generic');
const attachments = Array.isArray($json.delivery_attachments) ? $json.delivery_attachments : (Array.isArray(hints.attachments) ? hints.attachments : []);
const fallbackText = String($json.delivery_text || hints.fallback_text || reply.text || '').trim();
const preMetaText = String($json.delivery_text || hints.pre_meta_text || reply.text || '').trim();
const privateNoteSummary = String($json.private_note_content || hints.private_note_summary || '').trim();
const interactiveType = String($json.interactive_type || '').trim();
const conversation = $('Webhook').item.json.body?.conversation || {};
const account = $('Webhook').item.json.body?.account || {};
const recipient = String(conversation?.meta?.sender?.phone_number || conversation?.contact_inbox?.source_id || $('Webhook').item.json.body?.source_id || '').replace(/[^0-9]/g, '');
let route = String($json.delivery_route || '').trim() || 'chat_text';
let metaRequestBody = $json.meta_request_body || null;
let metaParseError = null;
if (metaRequestBody && typeof metaRequestBody === 'object') {
  metaRequestBody.messaging_product = 'whatsapp';
  if (!metaRequestBody.to && recipient) metaRequestBody.to = recipient;
} else if (supportsMeta && String(hints.preferred_delivery || '').trim() === 'meta_interactive') {
  const interactive = hints.meta_interactive || {};
  const metaRequestBodyJson = String(interactive.meta_request_body_json || '').trim();
  if (metaRequestBodyJson) {
    try {
      metaRequestBody = JSON.parse(metaRequestBodyJson);
      if (metaRequestBody && typeof metaRequestBody === 'object') {
        metaRequestBody.messaging_product = 'whatsapp';
        if (!metaRequestBody.to && recipient) metaRequestBody.to = recipient;
        route = 'meta_interactive';
      }
    } catch (error) {
      metaParseError = error.message;
    }
  }
}
if (!supportsMeta) route = 'chat_text';
const noteContent = privateNoteSummary || (route === 'meta_interactive' ? `Respuesta interactiva enviada por Meta (${interactiveType || 'interactive'}).` : '');
return [{ json: { ...$json, delivery_route: route, delivery_text: route === 'meta_interactive' ? preMetaText : fallbackText, delivery_attachments: attachments, supports_meta_interactive: supportsMeta, channel_family: channelFamily, meta_interactive_type: interactiveType || 'none', meta_request_body: metaRequestBody, meta_parse_error: metaParseError, private_note_content: noteContent, should_create_private_note: route === 'meta_interactive' && noteContent !== '', conversation_id: conversation.id, account_id: account.id, recipient_wa_id: recipient } }];

