  const sheetEstablishmentId = String(context.mcp_booking_state?.selected_establishment_id || '').trim();
  const sheetScheduleId = `vehicle_schedule${sheetProductId ? `__product_${sheetProductId}` : ''}${sheetEstablishmentId ? `__establishment_${sheetEstablishmentId}` : ''}`;
  const sheetFilename = `Ficha tecnica${sheetModel ? ` ${sheetModel}` : ''}.pdf`.replace(/[\\/:*?"<>|]/g, ' ').replace(/\s+/g, ' ').trim();
  const sheetCaption = sheetModel
    ? `Aquí tienes la ficha técnica de la KIA ${sheetModel} 📄`
    : 'Aquí tienes la ficha técnica 📄';
  const sheetCta = '¿Quieres agendar un test drive o explorar otros modelos?';
  strategy = {
    delivery_route: 'meta_gallery',
    interactive_type: 'gallery',
    delivery_text: `${sheetCaption}\n\n${sheetCta}`,
    private_note_content: `Ficha técnica entregada de forma determinista para producto ${sheetProductId || 'sin id'}.`,
    strategy_reason: 'techsheet_document_delivery',
    meta_request_body: null,
    delivery_attachments: [],
    use_meta_gallery: true,
    gallery_requests: [
      { field: 'techsheet', type: 'document', body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: phone, type: 'document', document: { link: techsheetUrl, filename: short(sheetFilename, 60), caption: short(sheetCaption, 1024) } } },
      { field: 'cta', type: 'interactive', body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: phone, type: 'interactive', interactive: { type: 'button', body: { text: short(sheetCta, 1024) }, action: { buttons: [
        { type: 'reply', reply: { id: sheetScheduleId, title: 'Agendar test drive' } },
        { type: 'reply', reply: { id: 'catalog', title: 'Ver otros modelos' } },
      ] } } } },
    ],
    gallery_media_fields: ['techsheet'],
    gallery_product_id: sheetProductId || null,
    source_message_id: String(nodeJson('Concatenar Buffer').buffer_last_message_id || nodeJson('Webhook').body?.id || ''),
  };
  return [{ json: { ...context, ...agentNode, ...strategy } }];
}

if (!isFinancingOnlyTurn && supportsMeta && exactDetailTurn && authoritativeProduct) {
  const productId = String(authoritativeProduct.id || bookingProductId || '').trim();
  const agentEstablishmentId = String(agentNode.output?.conversation_attributes?.establishment_id || '').trim();
  const establishmentId = String(callbackEstablishmentId || bookingState.selected_establishment_id || bookingState.establishment_id || bookingState.raw_custom_attributes?.selected_establishment_id || bookingState.raw_custom_attributes?.establishment_id || agentEstablishmentId || '').trim();
  const scheduleId = `vehicle_schedule__product_${productId}${establishmentId ? `__establishment_${establishmentId}` : ''}`;
  const detailButtons = [
    ...(hasTechsheet ? [{ type: 'reply', reply: { id: `techsheet__product_${productId}`, title: 'Ficha técnica' } }] : []),
    { type: 'reply', reply: { id: scheduleId, title: 'Agendar test drive' } },
    ...(hasTechsheet ? [] : [{ type: 'reply', reply: { id: 'catalog', title: 'Ver otros modelos' } }]),
  ];

  function splitVehicleDetailForDelivery(text, product) {
    const normalized = String(text || '').replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
    const fallbackFinal = 'Si quieres, te lo muestro en concesionario para que lo sientas en persona 🔑';
    if (!normalized) return { intro: String(product?.name || 'Este modelo').trim(), final: fallbackFinal };

    const paragraphs = normalized.split(/\n\s*\n/).map((part) => part.trim()).filter(Boolean);
    const ctaIndex = paragraphs.findIndex((part) => /\b(?:si quieres|te gustar[ií]a|conocer(?:lo|la)? en persona|arrancas?|test drive|concesionario|ver concesionarios)\b/i.test(part));
    // A CTA inside the first paragraph means the whole reply is the closing
    // message. Keeping it as intro too would deliver the same text twice.
    let introParts = ctaIndex > 0 ? paragraphs.slice(0, ctaIndex) : (ctaIndex === 0 ? [] : paragraphs);
    let finalParts = ctaIndex >= 0 ? paragraphs.slice(ctaIndex) : [];

    function isPriceOnly(part) {
      return /^(?:💰\s*)?(?:Precio:\s*)?(?:desde\s*)?\*?\$\s*[0-9][0-9.,]*\*?$/i.test(String(part || '').replace(/[*_~`]/g, '').trim());
    }

    const priceValue = productPriceValue(product?.price ?? product?.price_from);
    const priceLine = priceValue ? `Precio: desde ${String.fromCharCode(36)}${priceValue}` : '';
    // The closing message always carries the price, so the intro must not repeat it.
    introParts = priceLine
      ? introParts.filter((part) => !isPriceOnly(part))
      : introParts.filter((part, index) => !(isPriceOnly(part) && introParts.findIndex(isPriceOnly) !== index));
    finalParts = finalParts.filter((part) => !isPriceOnly(part));

    const intro = introParts.join('\n\n').trim() || (ctaIndex === 0 ? '' : normalized);
    const finalBase = finalParts.join('\n\n').trim() || fallbackFinal;
    const final = [finalBase, priceLine].filter(Boolean).join('\n\n');
    return { intro, final };
  }

  const detailParts = splitVehicleDetailForDelivery(replyText, authoritativeProduct);
  const requests = [];
  if (detailParts.intro) {
    requests.push({ field: 'intro', type: 'text', body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: phone, type: 'text', text: { body: short(detailParts.intro, 4096), preview_url: false } } });
  }
  for (const media of galleryMedia) {
    const payload = { link: media.url };
    if (media.type === 'document' && media.filename) payload.filename = media.filename;
    requests.push({
      field: media.field,
      type: media.type,
      body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: phone, type: media.type, [media.type]: payload },
    });
  }
  requests.push({ field: 'cta', type: 'interactive', body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: phone, type: 'interactive', interactive: { type: 'button', body: { text: short(detailParts.final, 1024) }, action: { buttons: detailButtons } } } });
  strategy = {
    delivery_route: 'meta_gallery',
    interactive_type: 'gallery',
    delivery_text: replyText,
    private_note_content: `Galería determinística ordenada para producto ${productId}: intro, ${galleryMedia.length} medios y CTA final.`,
    strategy_reason: 'exact_product_ordered_media_gallery',
    meta_request_body: null,
    delivery_attachments: [],
    use_meta_gallery: true,
    gallery_requests: requests,
    gallery_media_fields: galleryMedia.map((media) => media.field),
    gallery_video_mode: directVideoUrl ? 'direct_media' : (safeVideoUrl ? 'safe_link' : 'none'),
    gallery_product_id: productId,
    gallery_establishment_id: establishmentId || null,
    source_message_id: String(nodeJson('Concatenar Buffer').buffer_last_message_id || nodeJson('Webhook').body?.id || ''),
  };
  return [{ json: { ...context, ...agentNode, ...strategy } }];
}

const shouldRenderCityInventory = isBookingCityInventoryTurn
  || (isVisitLocationTurn && (!toolCardinalityKnown || dealerships.length === 0));

if (supportsMeta && shouldRenderCityInventory) {
  if (cityInventory?.ok === true && registeredCities.length > 0) {
    const pageSize = 8;
    const totalPages = Math.max(1, Math.ceil(registeredCities.length / pageSize));
    const page = Math.min(requestedCityPage, totalPages - 1);
    const rows = registeredCities.slice(page * pageSize, (page + 1) * pageSize).map((city) => ({
      id: `booking_city_${Buffer.from(city.name, 'utf8').toString('hex')}${productSuffix}`,
      title: short(city.name, 24),
      description: city.count === 1 ? '1 sede disponible' : `${city.count} sedes disponibles`,
    }));
    if (page > 0) rows.push({ id: `booking_cities_page_${page - 1}${productSuffix}`, title: 'Página anterior', description: 'Ver ciudades anteriores' });
    if (page < totalPages - 1) rows.push({ id: `booking_cities_page_${page + 1}${productSuffix}`, title: 'Página siguiente', description: 'Ver más ciudades' });
    const pageLabel = totalPages > 1 ? ` Página ${page + 1} de ${totalPages}.` : '';
    const cityText = `Elige la ciudad donde prefieres realizar tu test drive.${pageLabel}`;
    strategy = {
      delivery_route: 'meta_interactive',
      interactive_type: 'list',
      delivery_text: cityText,
      private_note_content: `Inventario determinista: ${registeredCities.length} ciudades activas agrupadas desde establishment_list_names.`,
      strategy_reason: 'booking_city_inventory',
      meta_request_body: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: phone,
        type: 'interactive',
        interactive: {
          type: 'list',
          body: { text: short(cityText, 1024) },
          action: { button: 'Elegir ciudad', sections: [{ title: 'Ciudades disponibles', rows }] },
        },
      },
      delivery_attachments: [],
    };
    return [{ json: { ...context, ...agentNode, ...strategy, booking_city_inventory: { count: registeredCities.length, page, total_pages: totalPages, source: 'establishment_list_names', origin_city: knownCity || null, product_id: bookingProductId || null } } }];
  }

  const inventoryUnavailableText = cityInventory?.ok === true
    ? 'En este momento no hay ciudades con sedes activas disponibles.'
    : (bookingInventoryRetry
      ? 'No pude consultar las ciudades disponibles después del reintento. Un asesor puede ayudarte a continuar.'
      : 'No pude consultar las ciudades disponibles. Puedes intentarlo una vez más.');
  if (bookingInventoryRetry || cityInventory?.ok === true) {
    strategy = {
      delivery_route: 'chat_text',
      interactive_type: 'none',
      delivery_text: inventoryUnavailableText,
      private_note_content: '',
      strategy_reason: bookingInventoryRetry ? 'booking_city_inventory_failed_after_retry' : 'booking_city_inventory_empty',
      meta_request_body: null,
      delivery_attachments: [],
    };
    return [{ json: { ...context, ...agentNode, ...strategy, booking_city_inventory: { count: 0, source: 'establishment_list_names', origin_city: knownCity || null, product_id: bookingProductId || null } } }];
  }

  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'list',
    delivery_text: inventoryUnavailableText,
    private_note_content: 'Se ofreció un único reintento determinista para consultar ciudades.',
    strategy_reason: 'booking_city_inventory_retry',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'list',
        body: { text: short(inventoryUnavailableText, 1024) },
        action: {
          button: 'Reintentar',
          sections: [{ title: 'Ciudades disponibles', rows: [{ id: `booking_cities_retry${productSuffix}`, title: 'Reintentar', description: 'Consultar ciudades nuevamente' }] }],
        },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...context, ...agentNode, ...strategy, booking_city_inventory: { count: null, source: 'establishment_list_names', origin_city: knownCity || null, product_id: bookingProductId || null } } }];
}

if (supportsMeta && isVisitLocationTurn && toolCardinalityKnown && dealerships.length === 1) {
  const dealer = dealerships[0];
  const detailLines = [
    `*${String(dealer.name).trim()}*`,
    dealer.address ? `📍 ${String(dealer.address).trim()}` : '',
    (dealer.schedules || dealer.hours) ? `🕐 ${String(dealer.schedules || dealer.hours).trim()}` : '',
    (dealer.site_url || dealer.map_url) ? `🗺️ ${String(dealer.site_url || dealer.map_url).trim()}` : '',
  ].filter(Boolean);
  const visitText = [
    searchedCity ? `Esta es la sede disponible en *${searchedCity}*:` : 'Esta es la sede disponible:',
    '',
    ...detailLines,
    '',
    '¿Quieres agendar tu test drive en esta sede?',
  ].join('\n');
  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'button',
    delivery_text: visitText,
    private_note_content: `Sede unica resuelta de forma determinista para establecimiento ${dealer.id}.`,
    strategy_reason: 'visit_single_dealership_direct',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: short(visitText, 1024) },
        action: {
          buttons: [
            { type: 'reply', reply: { id: `booking_other_city${productSuffix}`, title: 'Ver otras ciudades' } },
            { type: 'reply', reply: { id: `vehicle_schedule${bookingProductId ? `__product_${bookingProductId}` : ''}__establishment_${dealer.id}`, title: 'Agendar test drive' } },
          ],
        },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...context, ...agentNode, ...strategy, booking_location_resolution: { city: searchedCity, count: 1, establishment_id: dealer.id, product_id: bookingProductId || null } } }];
}

if (supportsMeta && isBookingLocationTurn && dealershipSearch?.ok && dealerships.length === 1) {
  const dealer = dealerships[0];
  const detailLines = [
    `📍 *${String(dealer.name).trim()}*`,
    dealer.address ? `📍 ${String(dealer.address).trim()}` : '',
    dealer.schedules ? `🕐 ${String(dealer.schedules).trim()}` : '',
    dealer.site_url ? `🗺️ ${String(dealer.site_url).trim()}` : '',
  ].filter(Boolean);
  const confirmationText = [
    searchedCity ? `Esta es la sede disponible en *${searchedCity}*:` : 'Esta es la sede disponible:',
    '',
    ...detailLines,
    '',
    '¿Confirmas esta sede para tu test drive?',
  ].join('\n');
  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'button',
    delivery_text: confirmationText,
    private_note_content: `Confirmacion de sede enviada para establecimiento ${dealer.id}.`,
    strategy_reason: 'booking_single_dealership_confirmation',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: short(confirmationText, 1024) },
        action: {
          buttons: [
            { type: 'reply', reply: { id: `booking_confirm_establishment_${dealer.id}`, title: 'Confirmar sede' } },
            { type: 'reply', reply: { id: 'booking_other_city', title: 'Otra ciudad' } },
          ],
        },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...context, ...agentNode, ...strategy, booking_location_resolution: { city: searchedCity, count: 1, establishment_id: dealer.id } } }];
}

if (supportsMeta && isBookingLocationTurn && dealershipSearch?.ok && dealerships.length > 1) {
  const rows = dealerships.slice(0, 9).map((dealer) => ({
    id: `booking_select_establishment_${dealer.id}${productSuffix}`,
    title: short(dealer.name, 24),
    description: short(dealer.address || dealer.schedules || searchedCity, 72),
  }));
  rows.push({ id: `booking_other_city${productSuffix}`, title: 'Otra ciudad', description: 'Ver ciudades disponibles' });
  const listText = searchedCity
    ? `Encontré ${dealerships.length} sedes en *${searchedCity}*. Elige la más cómoda para tu test drive.`
    : `Encontré ${dealerships.length} sedes. Elige la más cómoda para tu test drive.`;
  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'list',
    delivery_text: listText,
    private_note_content: `Lista de ${dealerships.length} sedes enviada para seleccion exacta.`,
    strategy_reason: 'booking_multiple_dealership_selection',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'list',
        body: { text: short(listText, 1024) },
        action: { button: 'Elegir sede', sections: [{ title: 'Sedes disponibles', rows }] },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...context, ...agentNode, ...strategy, booking_location_resolution: { city: searchedCity, count: dealerships.length, product_id: bookingProductId || null } } }];
}

strategy = {
  delivery_route: 'chat_text',
  interactive_type: 'none',
  delivery_text: fallbackText || replyText,
  private_note_content: '',
  strategy_reason: 'text_default',
  meta_request_body: null,
  delivery_attachments: Array.isArray(hints.attachments) ? hints.attachments : [],
};

if (!supportsMeta) {
  return [{ json: { ...context, ...agentNode, ...strategy } }];
}

if (explicitCatalogRequest && policy === 'prefer_carousel' && normalizedCatalog.length >= 2) {
  const cards = normalizedCatalog.slice(0, 10).map((item, idx) => ({
    card_index: idx,
    type: 'cta_url',
    header: { type: 'image', image: { link: item.image_url } },
    body: { text: short(item.name + (item.subtitle ? '\n' + item.subtitle : ''), 160) },
    action: {
      buttons: [
        { type: 'quick_reply', quick_reply: { id: slug(item.name) + '__mas_info', title: 'Más info' } },
        { type: 'quick_reply', quick_reply: { id: `vehicle_schedule__product_${item.id}`, title: 'Agendar test drive' } },
      ],
    },
  })).filter((card) => card.header.image.link);

  if (cards.length >= 2) {
    strategy = {
      delivery_route: 'meta_interactive',
      interactive_type: 'carousel',
      delivery_text: replyText || 'Te comparto algunas opciones destacadas.',
      private_note_content: privateNoteSummary || `Carrusel enviado con ${cards.length} vehículos para consulta de catálogo.`,
      strategy_reason: 'vehicle_family_carousel',
      meta_request_body: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: phone,
        type: 'interactive',
        interactive: {
          type: 'carousel',
          body: { text: short(replyText || 'Te comparto algunas opciones destacadas.', 1024) },
          action: { cards },
        },
      },
      delivery_attachments: [],
    };
    return [{ json: { ...context, ...agentNode, ...strategy } }];
  }
}

const detailProductId = String(authoritativeProduct?.id || context.selected_model_id || bookingProductId || normalizedCatalog[0]?.id || '').trim();
const outputEstablishmentId = String(agentNode.output?.conversation_attributes?.establishment_id || '').trim();
const detailEstablishmentId = String(callbackEstablishmentId || bookingState.selected_establishment_id || bookingState.establishment_id || bookingState.raw_custom_attributes?.selected_establishment_id || bookingState.raw_custom_attributes?.establishment_id || outputEstablishmentId || '').trim();
const detailScheduleId = `vehicle_schedule${detailProductId ? `__product_${detailProductId}` : ''}${detailEstablishmentId ? `__establishment_${detailEstablishmentId}` : ''}`;
const detailTechsheetUrl = techsheetUrl
  || catalogTechsheetUrl(detailProductId)
  || validHttps(normalizedCatalog.find((item) => String(item.id) === String(detailProductId))?.techsheet_url);
const detailHasTechsheet = Boolean(detailTechsheetUrl);
const productDetailQuickReplies = techsheetRequestTurn
  ? [
      { id: detailScheduleId, title: 'Agendar test drive' },
      { id: 'catalog', title: 'Ver otros modelos' },
    ]
  : exactDetailTurn
  ? [
      ...(detailHasTechsheet ? [{ id: `techsheet__product_${detailProductId}`, title: 'Ficha técnica' }] : []),
      { id: detailScheduleId, title: 'Agendar test drive' },
      ...(detailHasTechsheet ? [] : [{ id: 'catalog', title: 'Ver otros modelos' }]),
    ]
  : [
      { id: `catalog__product_${detailProductId}__more_info`, title: 'Más info' },
      { id: detailScheduleId, title: 'Agendar test drive' },
      { id: 'catalog', title: 'Ver otros modelos' },
    ];

if (!isFinancingOnlyTurn && (techsheetRequestTurn || policy === 'prefer_quick_reply_test_drive' || (primaryIntent === 'vehicle_info' && (selectedModel || normalizedCatalog.length === 1))) && productDetailQuickReplies.length >= 2) {
  const question = techsheetRequestTurn
    ? '¿Quieres agendar un test drive o explorar otros modelos?'
    : (exactDetailTurn
      ? (detailHasTechsheet
        ? '¿Quieres ver la ficha técnica o agendar un test drive?'
        : '¿Quieres agendar un test drive o explorar otros modelos?')
      : '¿Quieres ver más detalles, agendar un test drive o explorar otros modelos?');
  const isVehicleDetailTurn = /callback_intent:\s*vehicle_detail_exact\b/i.test(effectiveMessage)
    || primaryIntent === 'vehicle_info';
  const interactiveBodyText = containsNormalizedSentence(replyText, question)
    || (isVehicleDetailTurn && hasInPersonVehicleCta(replyText))
    ? replyText
    : [replyText, question].filter(Boolean).join('\n\n');

  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'button',
    delivery_text: replyText || question,
    private_note_content: privateNoteSummary || 'Botones rápidos enviados para continuar la conversación comercial del vehículo.',
    strategy_reason: 'vehicle_detail_quick_reply',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: short(interactiveBodyText || question, 1024) },
        action: {
          buttons: productDetailQuickReplies.map((item) => ({ type: 'reply', reply: { id: item.id, title: item.title } })),
        },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: {
    ...context,
    ...agentNode,
    ...strategy,
    product_detail_location_resolution: {
      city: knownCity || null,
      count: dealershipCount,
      source: dealershipCardinalitySource,
      dealership_selection_suppressed: suppressDealershipSelection,
    },
  } }];
}

if (policy === 'prefer_list' && normalizedListItems.length >= 2) {
  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'list',
    delivery_text: replyText || 'Te comparto opciones para que elijas.',
    private_note_content: privateNoteSummary || `Lista interactiva enviada con ${normalizedListItems.length} opciones.`,
    strategy_reason: 'multi_option_list',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'list',
        body: { text: short(replyText || 'Te comparto opciones para que elijas.', 1024) },
        action: { button: 'Ver opciones', sections: [{ title: 'Opciones', rows: normalizedListItems.slice(0, 10) }] },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...context, ...agentNode, ...strategy } }];
}

return [{ json: { ...context, ...agentNode, ...strategy } }];

const base = $('Set Conversation Intent').item.json || {};
const response = $json || {};
const action = response.next_action || {};

return [{
  json: {
    ...base,
    next_action_response: response,
    next_action: action,
    mcp_next_action_labels: response.labels_to_add || [],
    mcp_next_action_labels_result: response.labels_result || null,
  },
}];

